INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷80·晋高祖本纪·天福七年五月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/jiuwudaishi-080-942-may/source.txt", "note": "《旧五代史》卷80·晋高祖本纪·天福七年五月，段落 jiu-wudaishi-205deb4a7860-p001971；已核上下文及传主，纸本及异文待核。", "id": "4b91fda2-ec3a-5693-92b8-5a7a7b08163c"}, {"title": "旧五代史·卷80·晋高祖本纪·天福七年四月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/jiuwudaishi-080-942-remonstrance/source.txt", "note": "《旧五代史》卷80·晋高祖本纪·天福七年四月，段落 jiu-wudaishi-205deb4a7860-p001970；已核上下文及传主，纸本及异文待核。", "id": "5703039c-75e3-558e-b22e-3e8069ccce4a"}, {"title": "旧五代史·卷96·郑受益传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/jiuwudaishi-096-zheng-shouyi/source.txt", "note": "《旧五代史》卷96·郑受益传，段落 jiu-wudaishi-205deb4a7860-p002353；已核上下文及传主，纸本及异文待核。", "id": "44c9d517-8b27-5fef-8940-e716eb2bad77"}, {"title": "资治通鉴·卷283·天福七年五月及随后记载", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/tongjian-283-942-may/source.txt", "note": "《资治通鉴》卷283·天福七年五月及随后记载，段落 zizhi-tongjian-a63549944a71-p003362；已核上下文及传主，纸本及异文待核。", "id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}, {"title": "资治通鉴·卷283·天福七年四月·南汉继承", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/tongjian-283-942-southern-succession/source.txt", "note": "《资治通鉴》卷283·天福七年四月·南汉继承，段落 zizhi-tongjian-a63549944a71-p003361；已核上下文及传主，纸本及异文待核。", "id": "a55613fc-acd9-5886-ac71-a339272c2387"}, {"title": "新五代史·卷65·南汉世家·刘玢继位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/xinwudaishi-065-liu-bin-succession/source.txt", "note": "《新五代史》卷65·南汉世家·刘玢继位，段落 xin-wudaishi-b08f244b9241-p003278；已核上下文及传主，纸本及异文待核。", "id": "3c185836-d297-517e-86f7-5a029b7f254e"}, {"title": "新五代史·卷65·南汉世家·刘龑去世", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/xinwudaishi-065-liu-yan-death/source.txt", "note": "《新五代史》卷65·南汉世家·刘龑去世，段落 xin-wudaishi-b08f244b9241-p003277；已核上下文及传主，纸本及异文待核。", "id": "0d0e70f0-ef89-5444-9ba0-ce63e39af14d"}, {"title": "资治通鉴·卷283·天福七年春季", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/tongjian-283-942-spring/source.txt", "note": "《资治通鉴》卷283·天福七年春季，段落 zizhi-tongjian-a63549944a71-p003360；已核上下文及传主，纸本及异文待核。", "id": "51e3045e-685e-5f80-bb8e-2efc7cd67ab5"}]'::jsonb)
