INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "杨洪", "aliases": ["楊洪"], "era": "五代十国", "birth_year": null, "death_year": 942, "description": "张彦泽部下将领，逃离后在陕州被抓。942年《资治通鉴》记张彦泽醉中截断其手足并斩首。出生年未载。", "biography": null, "status": "draft", "id": "0b5448a2-9869-5bf1-a622-276f6bcf53ad"}, {"name": "王周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王周。", "biography": null, "status": "draft", "id": "dcf3a493-1cbc-5185-9787-8041333d1d90"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "郑受益", "aliases": ["鄭受益"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "唐宰相郑从谠的侄子，郑处诲之子。后晋右谏议大夫。942年四月上疏请求追究张彦泽虐民杀人的罪责。生卒年及后续履历本批未补定。", "biography": null, "status": "draft", "id": "ca6378a0-6c37-57bc-83c8-c673e179229c"}, {"name": "郑从谠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑从谠。", "biography": null, "status": "draft", "id": "15f99f06-f58e-5b7f-8845-549c1edaad2d"}, {"name": "郑处诲", "aliases": ["鄭處誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郑从谠的兄长，郑受益的父亲。《旧五代史》记他曾任汴州节度使。生卒年未载。", "biography": null, "status": "draft", "id": "5d3d9dde-9111-543d-9ee3-574c6d44dfa8"}, {"name": "李涛（后晋宋初官员）", "aliases": ["李濤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李澣的兄长，后晋至宋初官员。《宋史》记他宋初任兵部尚书，去世时六十四岁，年代与887年已在杨行密军中的同名李涛不相容，本批单独建档。生卒年不凭年龄反推，后续旧库记录需逐条核对。", "biography": null, "status": "draft", "id": "c03574d2-e4e9-5739-be38-c52f0c0de233"}, {"name": "张麟", "aliases": ["張麟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋刑部郎中。942年四月庚申与李涛、麻麟、王禧一起上疏请求追究张彦泽罪责。生卒年未载。", "biography": null, "status": "draft", "id": "dff2657d-7039-51c9-ae9c-608ccbc26ffb"}, {"name": "麻麟", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋员外郎。942年四月庚申与李涛、张麟、王禧一起上疏请求追究张彦泽罪责。生卒年未载。", "biography": null, "status": "draft", "id": "8b21b9d2-b485-5615-b917-48b103a719ec"}, {"name": "王禧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋员外郎。942年四月庚申与李涛、张麟、麻麟一起上疏请求追究张彦泽罪责。生卒年未载。", "biography": null, "status": "draft", "id": "bbf09fec-d241-5e1c-9354-f2567890e9e3"}, {"name": "张铎", "aliases": ["張鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋张式的父亲。942年到朝廷为儿子申冤。生卒年未载。", "biography": null, "status": "draft", "id": "76a2426d-a082-5fa7-a7a7-f4d155e0cce6"}, {"name": "刘岩", "aliases": ["刘龑", "劉巖", "劉龑", "劉岩", "刘巖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：刘岩。", "biography": null, "status": "draft", "id": "3b676280-64ca-5ba9-b78d-c6c5f257a018"}, {"name": "王翷", "aliases": ["王翻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉右仆射兼西御院使。刘岩病重时与他商议把刘弘度、刘弘熙调往外地，立刘弘昌；计划经萧益劝阻而停止。《新五代史》同次谋划写王翻，姓名异字保留。", "biography": null, "status": "draft", "id": "7d3d5c3d-e1e1-5028-a38b-e128bffa5ef0"}, {"name": "刘弘度", "aliases": ["劉弘度", "刘洪度", "劉洪度"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘度，获封王爵之子。", "biography": null, "status": "draft", "id": "9f834996-df40-5434-9360-acbf54bfe3c6"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘昌", "aliases": ["劉弘昌", "刘洪昌", "劉洪昌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘昌，获封王爵之子。", "biography": null, "status": "draft", "id": "fda27388-00bf-5390-90ae-9604e2ec1c33"}, {"name": "萧益", "aliases": ["蕭益"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉崇文使，萧仿的孙子。938年南汉出兵交州时，建议谨慎进军、选用熟悉地形的向导；刘岩没有听从。生卒年未载。", "biography": null, "status": "draft", "id": "8be0c6ac-cc0d-55d7-b6d9-3e2d1dd20527"}, {"name": "杨洞潜", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明三年条所见人物：杨洞潜。", "biography": null, "status": "draft", "id": "659742b2-9884-594d-9d51-e726ad018f77"}, {"name": "赵氏（刘弘度母）", "aliases": ["赵昭仪", "趙昭儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉刘弘度的母亲，原为昭仪。942年刘弘度即位并改名玢，尊她为皇太妃。姓名及生卒年未载。", "biography": null, "status": "draft", "id": "bc1ebd50-7a6e-5399-9f09-75689fd05c8c"}, {"name": "刘氏（石敬瑭太妃）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋皇太妃。942年五月乙巳被尊为皇太后。《资治通鉴》称她是石敬瑭的庶母，《旧五代史》所引徐无党注称生母，关系异说保留。姓名及出生年未载。", "biography": null, "status": "draft", "id": "57ccf847-6548-50a3-9346-b099fc0def3d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

